37	export async function createVertical(_prev: ActionState, formData: FormData): Promise<ActionState> {
38	  await requireArea("platform");
39	  const parsed = verticalSchema.safeParse({
40	    slug: formData.get("slug"),
41	    name: formData.get("name"),
42	    description: formData.get("description") ?? "",
43	  });
44	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid vertical." };
45	  const slug = slugify(parsed.data.slug);
46	
47	  const clash = await db.agencyVertical.findUnique({ where: { slug }, select: { id: true } });
48	  if (clash) return { error: "A vertical with that slug already exists." };
49	
50	  try {
51	    await db.agencyVertical.create({
52	      data: { slug, name: parsed.data.name, description: parsed.data.description },
53	    });
54	  } catch (err) {
55	    await logEvent("error", "agency.vertical.create", { message: String(err) });
56	    return { error: "Could not create the vertical." };
57	  }
58	  revalidatePath("/admin/agency/verticals");
59	  revalidatePath("/admin/agency");
60	  return { ok: true };
61	}
