76	/**
77	 * Create a template. The section schema is seeded to the five standard sections
78	 * (hero, services, about, testimonials, contact) so a template is immediately
79	 * usable; richer authoring is Phase 2.
80	 */
81	export async function createTemplate(_prev: ActionState, formData: FormData): Promise<ActionState> {
82	  await requireArea("platform");
83	  const parsed = templateSchema.safeParse({
84	    verticalId: formData.get("verticalId"),
85	    name: formData.get("name"),
86	  });
87	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid template." };
88	
89	  const vertical = await db.agencyVertical.findUnique({ where: { id: parsed.data.verticalId }, select: { id: true } });
90	  if (!vertical) return { error: "That vertical no longer exists." };
91	
92	  const structure = {
93	    sections: [
94	      { key: "hero", label: "Hero", required: true, guidance: "Headline + supporting line + call to action." },
95	      { key: "services", label: "Services", required: true, guidance: "3–6 core services." },
96	      { key: "about", label: "About", required: false, guidance: "A short trust-building paragraph." },
97	      { key: "testimonials", label: "Testimonials", required: false, guidance: "2–3 generic illustrative quotes." },
98	      { key: "contact", label: "Contact", required: true, guidance: "Closing CTA." },
99	    ],
100	  } satisfies Prisma.InputJsonValue;
101	
102	  try {
103	    await db.agencyTemplate.create({
104	      data: { verticalId: parsed.data.verticalId, name: parsed.data.name, structure },
105	    });
106	  } catch (err) {
107	    await logEvent("error", "agency.template.create", { message: String(err) });
108	    return { error: "Could not create the template." };
109	  }
110	  revalidatePath("/admin/agency/verticals");
111	  revalidatePath("/admin/agency");
112	  return { ok: true };
113	}
