138	export async function addProspect(_prev: ActionState, formData: FormData): Promise<ActionState> {
139	  await requireArea("platform");
140	  const parsed = prospectSchema.safeParse({
141	    businessName: formData.get("businessName"),
142	    vertical: formData.get("vertical") ?? "",
143	    contactEmail: formData.get("contactEmail") ?? "",
144	    currentSiteUrl: formData.get("currentSiteUrl") ?? "",
145	    pastedSiteText: formData.get("pastedSiteText") ?? "",
146	    notes: formData.get("notes") ?? "",
147	  });
148	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid prospect." };
149	
150	  const email = parsed.data.contactEmail;
151	  if (email && !emailCheck.safeParse(email).success) {
152	    return { error: "Enter a valid contact email or leave it blank." };
153	  }
154	
155	  try {
156	    await db.agencyProspect.create({
157	      data: {
158	        businessName: parsed.data.businessName,
159	        vertical: parsed.data.vertical ? slugify(parsed.data.vertical) : "",
160	        contactEmail: email || null,
161	        currentSiteUrl: parsed.data.currentSiteUrl || null,
162	        pastedSiteText: parsed.data.pastedSiteText,
163	        notes: parsed.data.notes,
164	      },
165	    });
166	  } catch (err) {
167	    await logEvent("error", "agency.prospect.add", { message: String(err) });
168	    return { error: "Could not add the prospect." };
169	  }
170	  revalidatePath("/admin/agency/prospects");
171	  revalidatePath("/admin/agency");
172	  return { ok: true };
173	}
