175	/**
176	 * Paste-a-CSV import. Columns (any order): business/name, vertical, email, url/website, notes.
177	 * Server-side parse, no enrichment, no scraping. Returns a summary in the channel.
178	 */
179	export async function importProspectsCsv(_prev: ActionState, formData: FormData): Promise<ActionState> {
180	  await requireArea("platform");
181	  const csv = String(formData.get("csv") ?? "");
182	  if (!csv.trim()) return { error: "Paste some CSV rows first." };
183	
184	  const { headers, rows } = parseCsv(csv);
185	  if (headers.length === 0 || rows.length === 0) {
186	    return { error: "Could not find a header row and at least one data row." };
187	  }
188	  const alias: Record<string, string> = {
189	    business: "businessName",
190	    businessname: "businessName",
191	    name: "businessName",
192	    company: "businessName",
193	    vertical: "vertical",
194	    category: "vertical",
195	    type: "vertical",
196	    email: "contactEmail",
197	    contactemail: "contactEmail",
198	    url: "currentSiteUrl",
199	    website: "currentSiteUrl",
200	    site: "currentSiteUrl",
201	    notes: "notes",
202	    note: "notes",
203	  };
204	  const cols = headers.map((h) => alias[h] ?? "");
205	  if (!cols.includes("businessName")) {
206	    return { error: "CSV needs at least a 'business' (name) column." };
207	  }
208	
209	  let created = 0;
210	  let skipped = 0;
211	  for (const r of rows) {
212	    const rec: Record<string, string> = {};
213	    cols.forEach((field, i) => {
214	      if (field) rec[field] = (r[i] ?? "").trim();
215	    });
216	    const businessName = (rec.businessName ?? "").trim();
217	    if (!businessName) {
218	      skipped++;
219	      continue;
220	    }
221	    const email = (rec.contactEmail ?? "").trim();
222	    try {
223	      await db.agencyProspect.create({
224	        data: {
225	          businessName: businessName.slice(0, 160),
226	          vertical: rec.vertical ? slugify(rec.vertical) : "",
227	          contactEmail: email && emailCheck.safeParse(email).success ? email : null,
228	          currentSiteUrl: (rec.currentSiteUrl ?? "").slice(0, 300) || null,
229	          notes: (rec.notes ?? "").slice(0, 2000),
230	        },
231	      });
232	      created++;
233	    } catch {
234	      skipped++;
235	    }
236	  }
237	  revalidatePath("/admin/agency/prospects");
238	  revalidatePath("/admin/agency");
239	  return { ok: true, error: `Imported ${created} prospect${created === 1 ? "" : "s"}${skipped ? `, skipped ${skipped}` : ""}.` };
240	}
