251	const STATUS_VALUES = ["PROSPECT", "GENERATED", "SENT", "WON", "LOST"] as const;
252	
253	export async function setProspectStatus(id: string, status: string): Promise<ActionState> {
254	  await requireArea("platform");
255	  if (!STATUS_VALUES.includes(status as (typeof STATUS_VALUES)[number])) {
256	    return { error: "Invalid status." };
257	  }
258	  await db.agencyProspect
259	    .update({ where: { id }, data: { status: status as (typeof STATUS_VALUES)[number] } })
260	    .catch(() => null);
261	  revalidatePath("/admin/agency/prospects");
262	  revalidatePath("/admin/agency");
263	  return { ok: true };
264	}
