266	// ---------------------------------------------------------------------------
267	// Demo generation + deploy stub
268	// ---------------------------------------------------------------------------
269	
270	/**
271	 * Generate a spec-site demo for a prospect: run the generator (LLM or fallback),
272	 * render deterministic HTML with the legal guardrails, persist the demo + a
273	 * generation log, and advance the prospect to GENERATED. No network to the
274	 * prospect's site; no deploy.
275	 */
276	export async function generateDemo(prospectId: string): Promise<ActionState> {
277	  await requireArea("platform");
278	  const prospect = await db.agencyProspect.findUnique({ where: { id: prospectId } });
279	  if (!prospect) return { error: "Prospect not found." };
280	
281	  const vertical = prospect.vertical || "dentist";
282	  // Pick a matching template if one exists (used to constrain the section schema).
283	  const dbVertical = await db.agencyVertical.findUnique({
284	    where: { slug: vertical },
285	    include: { templates: { orderBy: { createdAt: "asc" }, take: 1 } },
286	  });
287	  const template = dbVertical?.templates[0] ?? null;
288	  const structure = template ? asTemplateStructure(template.structure) : undefined;
289	
290	  const slug = slugify(prospect.businessName);
291	
292	  let ir: SiteIR;
293	  let genMode = "fallback";
294	  let genModel = "";
295	  let genOk = true;
296	  let genMsg = "";
297	  try {
298	    const result = await generateSiteIR({
299	      businessName: prospect.businessName,
300	      vertical,
301	      slug,
302	      pastedSiteText: prospect.pastedSiteText,
303	      structure,
304	    });
305	    ir = result.ir;
306	    genMode = result.mode;
307	    genModel = result.model;
308	    genOk = result.ok;
309	    genMsg = result.message;
310	  } catch (err) {
311	    await logEvent("error", "agency.demo.generate", { message: String(err), prospectId });
312	    return { error: "Generation failed. Please try again." };
313	  }
314	
315	  const rendered = renderSiteHtml(ir);
316	  if (!rendered.guardrailsOk) {
317	    // Never persist a demo missing a mandatory legal guardrail.
318	    await logEvent("error", "agency.demo.guardrails", { prospectId, message: "guardrail assertion failed" });
319	    return { error: "Render failed a legal guardrail check and was not saved." };
320	  }
321	
322	  try {
323	    const demo = await db.agencyDemoSite.create({
324	      data: {
325	        prospectId: prospect.id,
326	        templateId: template?.id ?? null,
327	        siteIR: ir as unknown as Prisma.InputJsonValue,
328	        renderedHtml: rendered.html,
329	        slug,
330	        status: "GENERATED",
331	        noindex: true,
332	      },
333	    });
334	    await db.agencyGenerationLog.create({
335	      data: { demoId: demo.id, mode: genMode, model: genModel, ok: genOk, message: genMsg.slice(0, 500) },
336	    });
337	    if (prospect.status === "PROSPECT") {
338	      await db.agencyProspect.update({ where: { id: prospect.id }, data: { status: "GENERATED" } });
339	    }
340	  } catch (err) {
341	    await logEvent("error", "agency.demo.persist", { message: String(err), prospectId });
342	    return { error: "Could not save the generated demo." };
343	  }
344	
345	  revalidatePath("/admin/agency/demos");
346	  revalidatePath("/admin/agency/prospects");
347	  revalidatePath("/admin/agency");
348	  return { ok: true };
349	}
