351	/**
352	 * STUB deploy. Records the intended host (slug.agency.revsports.ca) and marks the
353	 * demo DEPLOYED_STUB. Real subdomain provisioning is Phase 2 — nothing is written
354	 * to nginx, DNS, or the filesystem here.
355	 */
356	export async function deployDemoStub(demoId: string): Promise<ActionState> {
357	  await requireArea("platform");
358	  const demo = await db.agencyDemoSite.findUnique({ where: { id: demoId }, select: { id: true, slug: true } });
359	  if (!demo) return { error: "Demo not found." };
360	  await db.agencyDemoSite
361	    .update({
362	      where: { id: demoId },
363	      data: { status: "DEPLOYED_STUB", intendedHost: intendedHostFor(demo.slug), deployedAt: new Date() },
364	    })
365	    .catch(() => null);
366	  await logEvent("info", "agency.demo.deploy_stub", { demoId, host: intendedHostFor(demo.slug) });
367	  revalidatePath("/admin/agency/demos");
368	  revalidatePath("/admin/agency");
369	  return { ok: true };
370	}
