381	// Cold Email Engine integration — "Send to outreach"
382	// ---------------------------------------------------------------------------
383	
384	/**
385	 * Create (or link) a Cold Email Business + Contact from a prospect, so the
386	 * prospect can flow into the existing outreach pipeline. Does NOT send anything —
387	 * it only creates the CRM records and stamps the prospect SENT. Reuses the
388	 * coldemail Business/Contact models directly.
389	 */
390	export async function sendToOutreach(prospectId: string): Promise<ActionState> {
391	  await requireArea("platform");
392	  const prospect = await db.agencyProspect.findUnique({ where: { id: prospectId } });
393	  if (!prospect) return { error: "Prospect not found." };
394	  if (prospect.outreachBusinessId) {
395	    return { error: "This prospect is already linked to an outreach business." };
396	  }
397	
398	  try {
399	    const business = await db.business.create({
400	      data: {
401	        name: prospect.businessName,
402	        category: prospect.vertical || "",
403	        website: prospect.currentSiteUrl || "",
404	        source: "manual",
405	      },
406	    });
407	
408	    // Attach a contact only when we have a valid, not-already-used email.
409	    if (prospect.contactEmail && emailCheck.safeParse(prospect.contactEmail).success) {
410	      const existing = await db.contact.findUnique({
411	        where: { email: prospect.contactEmail },
412	        select: { id: true },
413	      });
414	      if (!existing) {
415	        await db.contact.create({
416	          data: { businessId: business.id, email: prospect.contactEmail },
417	        });
418	      }
419	    }
420	
421	    await db.agencyProspect.update({
422	      where: { id: prospect.id },
423	      data: { outreachBusinessId: business.id, status: prospect.status === "PROSPECT" ? "SENT" : prospect.status === "GENERATED" ? "SENT" : prospect.status },
424	    });
425	  } catch (err) {
426	    await logEvent("error", "agency.outreach.link", { message: String(err), prospectId });
427	    return { error: "Could not link the prospect to outreach." };
428	  }
429	
430	  revalidatePath("/admin/agency/prospects");
431	  revalidatePath("/admin/coldemail/businesses");
432	  revalidatePath("/admin/agency");
433	  return { ok: true };
434	}
