436	// ---------------------------------------------------------------------------
437	// CSV parser (server-side, no dependency). Handles quotes, commas, newlines.
438	// ---------------------------------------------------------------------------
439	
440	function parseCsv(text: string): { headers: string[]; rows: string[][] } {
441	  const records: string[][] = [];
442	  let field = "";
443	  let row: string[] = [];
444	  let inQuotes = false;
445	  const src = text.replace(/\r\n?/g, "\n");
446	  for (let i = 0; i < src.length; i++) {
447	    const c = src[i];
448	    if (inQuotes) {
449	      if (c === '"') {
450	        if (src[i + 1] === '"') {
451	          field += '"';
452	          i++;
453	        } else {
454	          inQuotes = false;
455	        }
456	      } else {
457	        field += c;
458	      }
459	    } else if (c === '"') {
460	      inQuotes = true;
461	    } else if (c === ",") {
462	      row.push(field);
463	      field = "";
464	    } else if (c === "\n") {
465	      row.push(field);
466	      records.push(row);
467	      row = [];
468	      field = "";
469	    } else {
470	      field += c;
471	    }
472	  }
473	  if (field.length > 0 || row.length > 0) {
474	    row.push(field);
475	    records.push(row);
476	  }
477	  const nonEmpty = records.filter((r) => r.some((v) => v.trim() !== ""));
478	  if (nonEmpty.length === 0) return { headers: [], rows: [] };
479	  const headers = nonEmpty[0].map((h) => h.trim().toLowerCase());
480	  return { headers, rows: nonEmpty.slice(1) };
481	}
