1	/**
2	 * Sitewave — Site IR (Intermediate Representation) + section-schema types and
3	 * validation.
4	 *
5	 * The generator (lib/agency/generate.ts) emits a Site IR, NOT raw HTML. The
6	 * deterministic renderer (lib/agency/render.ts) maps a validated IR to a
7	 * self-contained static HTML page. Validation lives here so both the LLM path
8	 * and the fallback path produce the exact same, safe shape.
9	 *
10	 * This module is pure (no imports of db / next / anthropic) so it can be unit
11	 * tested and reused server-side without side effects.
12	 */
13	
14	// ---------------------------------------------------------------------------
15	// Section schema — what a vertical template constrains the generated site to.
16	// ---------------------------------------------------------------------------
17	
18	export type SectionKey = "hero" | "services" | "about" | "testimonials" | "contact";
19	
20	export const SECTION_KEYS: SectionKey[] = ["hero", "services", "about", "testimonials", "contact"];
21	
22	export type SectionSchemaEntry = {
23	  key: SectionKey;
24	  label: string;
25	  required: boolean;
26	  /** Human guidance fed to the LLM for this section's copy. */
27	  guidance: string;
28	};
29	
30	export type TemplateStructure = {
31	  sections: SectionSchemaEntry[];
32	  /** Optional palette hint the template suggests to the generator. */
33	  palette?: { primary?: string; accent?: string };
34	};
35	
36	/** Narrow an unknown Json value from Prisma into a TemplateStructure, defensively. */
37	export function asTemplateStructure(value: unknown): TemplateStructure {
38	  const v = (value ?? {}) as { sections?: unknown; palette?: unknown };
39	  const rawSections = Array.isArray(v.sections) ? v.sections : [];
40	  const sections: SectionSchemaEntry[] = rawSections
41	    .map((s) => s as Partial<SectionSchemaEntry>)
42	    .filter((s): s is SectionSchemaEntry => typeof s?.key === "string" && SECTION_KEYS.includes(s.key as SectionKey))
43	    .map((s) => ({
44	      key: s.key,
45	      label: String(s.label ?? s.key),
46	      required: Boolean(s.required),
47	      guidance: String(s.guidance ?? ""),
48	    }));
49	  const palette = (v.palette ?? undefined) as TemplateStructure["palette"];
50	  return { sections, palette };
51	}
52	
53	// ---------------------------------------------------------------------------
54	// Site IR — the structured output the generator produces.
55	// ---------------------------------------------------------------------------
56	
57	export type IRService = { name: string; description: string };
58	export type IRTestimonial = { quote: string; author: string };
59	
60	export type SiteIR = {
61	  businessName: string;
62	  vertical: string;
63	  hero: { headline: string; subheadline: string; ctaLabel: string };
64	  services: IRService[];
65	  about: string;
66	  testimonials: IRTestimonial[];
67	  contact: { ctaHeadline: string; ctaBody: string; buttonLabel: string };
68	  /** A suggested — INSPIRED-BY, not exact-brand — palette (legal guardrail). */
69	  palette: { primary: string; accent: string };
70	};
71	
72	const HEX = /^#[0-9a-fA-F]{6}$/;
73	
74	function str(v: unknown, fallback = ""): string {
75	  return typeof v === "string" && v.trim() ? v.trim() : fallback;
76	}
77	
78	function clampArray<T>(v: unknown, map: (x: unknown) => T | null, max: number): T[] {
79	  if (!Array.isArray(v)) return [];
80	  const out: T[] = [];
81	  for (const item of v) {
82	    const m = map(item);
83	    if (m) out.push(m);
84	    if (out.length >= max) break;
85	  }
86	  return out;
87	}
88	
89	/**
90	 * Coerce an arbitrary object (LLM JSON or a fallback build) into a fully-valid
91	 * SiteIR. NEVER throws: every field is defaulted so the renderer always has a
92	 * safe, complete IR. `defaults` supplies sensible per-vertical text when a field
93	 * is missing (used by the deterministic fallback).
94	 */
95	export function coerceSiteIR(
96	  raw: unknown,
97	  defaults: { businessName: string; vertical: string; palette?: { primary: string; accent: string } }
98	): SiteIR {
99	  const o = (raw ?? {}) as Record<string, unknown>;
100	  const hero = (o.hero ?? {}) as Record<string, unknown>;
101	  const contact = (o.contact ?? {}) as Record<string, unknown>;
102	  const paletteIn = (o.palette ?? {}) as Record<string, unknown>;
103	
104	  const primary = HEX.test(str(paletteIn.primary)) ? str(paletteIn.primary) : (defaults.palette?.primary ?? "#4F46E5");
105	  const accent = HEX.test(str(paletteIn.accent)) ? str(paletteIn.accent) : (defaults.palette?.accent ?? "#FB7185");
106	
