5	export const runtime = "nodejs";
6	export const dynamic = "force-dynamic";
7	
8	/**
9	 * Serve a generated Sitewave demo's stored HTML for PREVIEW.
10	 *
11	 * GET /api/agency/demo/<id>/preview — returns the deterministically rendered,
12	 * self-contained HTML of the demo (admin/platform staff only). The response
13	 * carries `X-Robots-Tag: noindex, nofollow` on top of the `<meta robots>` the
14	 * renderer already bakes in, so a previewed demo can never be indexed. This is a
15	 * read-only preview surface — it renders stored bytes and provisions nothing.
16	 */
17	export async function GET(_req: Request, ctx: { params: Promise<{ id: string }> }) {
18	  const user = await realUser();
19	  if (!user || !isStaff(user.role) || !canAccess(user.role, "platform")) {
20	    return new Response("Not found", { status: 404 });
21	  }
22	
23	  const { id } = await ctx.params;
24	  const demo = await db.agencyDemoSite.findUnique({
25	    where: { id },
26	    select: { renderedHtml: true },
27	  });
28	  if (!demo || !demo.renderedHtml) {
29	    return new Response("Demo not found", { status: 404 });
30	  }
31	
32	  return new Response(demo.renderedHtml, {
33	    status: 200,
34	    headers: {
35	      "content-type": "text/html; charset=utf-8",
36	      "x-robots-tag": "noindex, nofollow",
37	      "cache-control": "no-store",
38	      // Defensive: the demo is self-contained, but forbid it from being framed
39	      // by any third-party origin.
40	      "content-security-policy": "frame-ancestors 'self'",
41	    },
42	  });
43	}
