77	/**
78	 * Run every probe for the app. Throws with the real HTTP result on the first
79	 * failure — an install that cannot be proved is a FAILED install, never a
80	 * quietly-downgraded one. Returns a one-line proof for the audit trail.
81	 */
82	export async function verifyServing(conn: Client, domain: string, probes: Probe[]): Promise<string> {
83	  const proof: string[] = [];
84	  for (const p of probes) {
85	    const { code, body } = await httpProbe(conn, domain, p.path);
86	    if (!(p.codes ?? ["200"]).includes(code))
87	      throw new Error(`verification failed: ${p.path} returned HTTP ${code}, so ${p.proves} is not true.`);
88	    for (const re of p.reject ?? []) {
89	      const hit = re.exec(body);
90	      if (hit) throw new Error(`verification failed: ${p.path} returned an application error ("${hit[0].slice(0, 80)}").`);
91	    }
92	    for (const re of p.require) {
93	      if (!re.test(body))
94	        throw new Error(`verification failed: ${p.path} answered 200 but ${p.proves} could not be confirmed.`);
95	    }
96	    proof.push(`${p.path}=${code}`);
97	  }
98	  return `verified from the VM (${proof.join(" ")})`;
99	}
