80	const BLOCKED_NAMES = new Set(["localhost", "localhost.localdomain", "ip6-localhost"]);
81	
82	/** Basic hostname sanity: letters/digits/hyphens/dots, or a literal IP. */
83	export function isPlausibleHost(host: string): boolean {
84	  if (!host || host.length > 253) return false;
85	  if (net.isIP(host)) return true;
86	  return /^(?!-)[a-zA-Z0-9-]{1,63}(?<!-)(\.(?!-)[a-zA-Z0-9-]{1,63}(?<!-))*$/.test(host);
87	}
