89	/**
90	 * Normalize an arbitrary user string into a bare hostname: strips a scheme,
91	 * path, port, and surrounding whitespace, and lower-cases. Returns null if
92	 * nothing host-like remains.
93	 */
94	export function extractHost(input: string): string | null {
95	  let s = (input || "").trim();
96	  if (!s) return null;
97	  // If it looks like a URL, let URL() pull the host out (handles ports, paths).
98	  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(s)) {
99	    try {
100	      s = new URL(s).hostname;
101	    } catch {
102	      return null;
103	    }
104	  } else {
105	    // Strip any path / query and a trailing :port (but keep bracketed IPv6).
106	    s = s.split("/")[0].split("?")[0];
107	    if (s.startsWith("[")) {
108	      const end = s.indexOf("]");
109	      if (end !== -1) s = s.slice(1, end);
110	    } else if (s.includes(":") && net.isIP(s) === 0) {
111	      s = s.split(":")[0];
112	    }
113	  }
114	  s = s.replace(/\.$/, "").toLowerCase();
115	  return s || null;
116	}
