118	export type ResolvedHost = { host: string; addresses: string[] };
119	
120	/**
121	 * Resolve `host` to its A/AAAA records and assert every one is a public address.
122	 * Throws BlockedHostError on any private / loopback / reserved target or on a
123	 * bare localhost. Returns the resolved addresses so callers can connect to a
124	 * vetted IP (defeating DNS rebinding).
125	 */
126	export async function resolvePublicHost(host: string): Promise<ResolvedHost> {
127	  const h = host.toLowerCase();
128	  if (BLOCKED_NAMES.has(h)) throw new BlockedHostError("This host is not allowed.");
129	  if (!isPlausibleHost(h)) throw new BlockedHostError("That doesn't look like a valid host.");
130	
131	  // A literal IP: no DNS, just classify it directly.
132	  if (net.isIP(h)) {
133	    if (isBlockedIp(h)) throw new BlockedHostError("Private, loopback, and reserved addresses are not allowed.");
134	    return { host: h, addresses: [h] };
135	  }
136	
137	  let results: { address: string }[];
138	  try {
139	    results = await lookup(h, { all: true });
140	  } catch {
141	    throw new BlockedHostError("Could not resolve that hostname.");
142	  }
143	  if (!results.length) throw new BlockedHostError("Could not resolve that hostname.");
144	
145	  const addresses = results.map((r) => r.address);
146	  for (const addr of addresses) {
147	    if (isBlockedIp(addr)) {
148	      throw new BlockedHostError("This host resolves to a private or reserved address and is not allowed.");
149	    }
150	  }
151	  return { host: h, addresses };
152	}
