/// Lifecycle of a prospect through the demo-gen funnel. Phase 1 only ever moves
/// a row PROSPECT -> GENERATED (on demo gen) and lets an operator mark SENT /
/// WON / LOST manually. No automation transitions these yet. Phase 2 keeps this
/// (additive) and adds the richer CRM `stage` below.
enum AgencyProspectStatus {
  PROSPECT
  GENERATED
  SENT
  WON
  LOST
}

/// PHASE 2 — CRM deal pipeline stage for a prospect. A separate axis from the
/// Phase 1 `status`: `stage` is the kanban column shown at /admin/agency/pipeline.
enum AgencyDealStage {
  LEAD
  CONTACTED
  DEMO_SENT
  NEGOTIATING
  WON
  LOST
}

/// PHASE 2 — the kind of a per-prospect activity-log entry.
enum AgencyActivityKind {
  NOTE
  STAGE_CHANGE
  SCRAPE
  DEMO
  QUOTE
  CONVERT
  SYSTEM
}

/// PHASE 2 — lifecycle of a client quote/proposal.
enum AgencyQuoteStatus {
  DRAFT
  SENT
  ACCEPTED
  DECLINED
}

  notes          String               @default("")
  status         AgencyProspectStatus @default(PROSPECT)
  /// PHASE 2 — CRM pipeline stage (separate axis from `status`). Drives the
  /// /admin/agency/pipeline kanban.
  stage          AgencyDealStage      @default(LEAD)
  /// PHASE 2 — estimated deal value in cents (operator-set; used in the pipeline
  /// header roll-up). Additive, defaults to 0.
  dealValueCents Int                  @default(0)
  /// PHASE 2 — the raw result of the last OPERATOR-TRIGGERED scrape of
  /// currentSiteUrl (business name, headings, services, contacts, colour hint).
  /// Never auto-crawled. Shape defined in lib/agency/scrape.ts (ScrapeResult).
  scrapeJson     Json                 @default("{}")
  scrapeStatus   String               @default("")
  scrapedAt      DateTime?
  /// Set once "Send to outreach" links this prospect to a Cold Email Business.
  outreachBusinessId String?
  createdAt      DateTime             @default(now())

  demos      AgencyDemoSite[]
  activities AgencyActivity[]
  client     AgencyClient?

  @@index([status])
  @@index([stage])
  @@index([vertical])
  @@index([createdAt])
}

renderedHtml String           @default("")
slug         String
status       AgencyDemoStatus @default(DRAFT)
noindex      Boolean          @default(true)
/// PHASE 2 — snapshot of the scrape extraction that informed THIS demo (so a
/// demo remembers the context it was generated from even if the prospect is
/// re-scraped later). Shape: ScrapeResult from lib/agency/scrape.ts.
extractionJson Json           @default("{}")
/// Recorded when "Deploy to subdomain" is clicked (the intended host).
intendedHost String?
