/// PHASE 2 — an append-only activity/note log entry for a prospect (CRM audit
/// trail): manual notes, stage changes, scrape/demo/quote/convert events.
model AgencyActivity {
  id         String             @id @default(cuid())
  prospectId String
  kind       AgencyActivityKind @default(NOTE)
  body       String             @default("")
  /// Optional structured context (e.g. { from, to } for a stage change).
  meta       Json               @default("{}")
  createdAt  DateTime           @default(now())

  prospect AgencyProspect @relation(fields: [prospectId], references: [id], onDelete: Cascade)

  @@index([prospectId])
  @@index([createdAt])
}

/// PHASE 2 — a won prospect converted into a client + project. One per prospect
/// (unique). Holds the project and its quotes.
model AgencyClient {
  id           String   @id @default(cuid())
  prospectId   String   @unique
  businessName String
  projectName  String   @default("Website project")
  contactEmail String?
  notes        String   @default("")
  createdAt    DateTime @default(now())

  prospect AgencyProspect @relation(fields: [prospectId], references: [id], onDelete: Cascade)
  quotes   AgencyQuote[]

  @@index([createdAt])
}

/// PHASE 2 — a self-contained quote/proposal for a client: line items + an
/// optional whole-number tax rate. The total is COMPUTED (lib/agency/quote.ts),
/// never stored, so it can never drift from the line items.
model AgencyQuote {
  id         String            @id @default(cuid())
  clientId   String
  title      String            @default("Website project")
  status     AgencyQuoteStatus @default(DRAFT)
  currency   String            @default("USD")
  /// Whole-percent tax rate applied to the subtotal (0–100).
  taxRatePct Int               @default(0)
  notes      String            @default("")
  createdAt  DateTime          @default(now())

  client    AgencyClient          @relation(fields: [clientId], references: [id], onDelete: Cascade)
  lineItems AgencyQuoteLineItem[]

  @@index([clientId])
  @@index([createdAt])
}

/// PHASE 2 — one line on a quote. `unitCents` is the price per unit in cents.
model AgencyQuoteLineItem {
  id          String   @id @default(cuid())
  quoteId     String
  description String
  quantity    Int      @default(1)
  unitCents   Int      @default(0)
  sortOrder   Int      @default(0)
  createdAt   DateTime @default(now())

  quote AgencyQuote @relation(fields: [quoteId], references: [id], onDelete: Cascade)

  @@index([quoteId])
}

