/**
 * Sitewave — PHASE 2 quote math. Pure (no db / next / anthropic imports) so it
 * unit-tests cleanly and the server action and the UI compute identical totals.
 *
 * Money is integer cents throughout — never floats — so rounding is explicit and
 * a total can never drift from its line items. Quantities and the tax rate are
 * clamped defensively so a hand-crafted POST cannot produce a negative or absurd
 * total.
 */

export type QuoteLine = {
  description: string;
  quantity: number;
  unitCents: number;
};

export type QuoteTotals = {
  /** Sum of quantity * unitCents across all lines, in cents. */
  subtotalCents: number;
  /** Tax applied to the subtotal, rounded to the nearest cent. */
  taxCents: number;
  /** subtotalCents + taxCents. */
  totalCents: number;
};

/** Clamp to a non-negative safe integer. */
function nonNeg(n: unknown): number {
  const v = Math.floor(Number(n));
  if (!Number.isFinite(v) || v < 0) return 0;
  return Math.min(v, Number.MAX_SAFE_INTEGER);
}

/** Clamp a whole-percent tax rate into [0, 100]. */
export function clampTaxRate(pct: unknown): number {
  const v = Math.round(Number(pct));
  if (!Number.isFinite(v)) return 0;
  return Math.max(0, Math.min(100, v));
}

/** Total for a single line, in cents (quantity * unitCents, both clamped). */
export function lineTotalCents(line: QuoteLine): number {
  return nonNeg(line.quantity) * nonNeg(line.unitCents);
}

/**
 * Compute subtotal, tax and total for a set of lines. Deterministic and pure.
 * Tax is `round(subtotal * pct / 100)` so it always lands on a whole cent.
 */
export function quoteTotals(lines: QuoteLine[], taxRatePct: number): QuoteTotals {
  const subtotalCents = lines.reduce((sum, l) => sum + lineTotalCents(l), 0);
  const pct = clampTaxRate(taxRatePct);
  const taxCents = Math.round((subtotalCents * pct) / 100);
  return { subtotalCents, taxCents, totalCents: subtotalCents + taxCents };
}

/** Format integer cents as a currency string (e.g. 125000 -> "$1,250.00"). */
export function formatCents(cents: number, currency = "USD"): string {
  const safe = Number.isFinite(cents) ? cents : 0;
  try {
    return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(safe / 100);
  } catch {
    // Unknown currency code — fall back to a bare number + code.
    return `${(safe / 100).toFixed(2)} ${currency}`;
  }
}

/** Parse a user-entered price string ("1,250.50", "$1250") into cents. */
export function parsePriceToCents(input: string): number {
  const cleaned = String(input ?? "").replace(/[^0-9.]/g, "");
  if (!cleaned) return 0;
  const value = Number(cleaned);
  if (!Number.isFinite(value) || value < 0) return 0;
  return Math.round(value * 100);
}

/**
 * Sitewave — PHASE 2 CRM pipeline stage helpers. Pure (no db / next imports) so
 * the transition rules are unit-tested and the server action + kanban UI agree.
 *
 * The pipeline is a simple linear funnel with two terminal states. We allow any
 * forward move and a move back one step (an operator correcting a mis-click),
 * plus reopening a WON/LOST deal — but we reject nonsense like LEAD -> WON in one
 * jump so the funnel stats stay meaningful.
 */

export const DEAL_STAGES = [
  "LEAD",
  "CONTACTED",
  "DEMO_SENT",
  "NEGOTIATING",
  "WON",
  "LOST",
] as const;

export type DealStage = (typeof DEAL_STAGES)[number];

/** Human labels for the kanban columns (sentence case). */
export const STAGE_LABELS: Record<DealStage, string> = {
  LEAD: "Lead",
  CONTACTED: "Contacted",
  DEMO_SENT: "Demo sent",
  NEGOTIATING: "Negotiating",
  WON: "Won",
  LOST: "Lost",
};

/** The ordered, non-terminal progression a deal walks through. */
const PROGRESSION: DealStage[] = ["LEAD", "CONTACTED", "DEMO_SENT", "NEGOTIATING"];

export function isDealStage(v: unknown): v is DealStage {
  return typeof v === "string" && (DEAL_STAGES as readonly string[]).includes(v);
}

export function isTerminal(stage: DealStage): boolean {
  return stage === "WON" || stage === "LOST";
}

/**
 * Is moving `from` -> `to` a legal transition?
 *
 * Rules:
 *  - staying put is a no-op, always allowed;
 *  - from any non-terminal stage you may advance any number of steps forward,
 *    step back exactly one, or close the deal (WON / LOST);
 *  - a terminal deal (WON / LOST) may be REOPENED to any non-terminal stage, or
 *    flipped between WON and LOST;
 *  - anything else is rejected.
 */
export function canTransition(from: DealStage, to: DealStage): boolean {
  if (!isDealStage(from) || !isDealStage(to)) return false;
  if (from === to) return true;

  // Terminal -> reopen to a non-terminal, or WON<->LOST.
  if (isTerminal(from)) {
    if (!isTerminal(to)) return true;
    return true; // WON <-> LOST flip
  }

  // Non-terminal -> terminal is always allowed (close the deal).
  if (isTerminal(to)) return true;

  // Non-terminal -> non-terminal: forward any distance, or back exactly one.
  const fi = PROGRESSION.indexOf(from);
  const ti = PROGRESSION.indexOf(to);
  if (fi < 0 || ti < 0) return false;
  if (ti > fi) return true; // forward
  return fi - ti === 1; // back one step only
}
